<script setup>
import {computed,ref} from 'vue'
import * as XLSX from 'xlsx'
import {Activity,AlertTriangle,ArrowDownToLine,ArrowUpFromLine,BarChart3,Bell,Boxes,Building2,ChevronDown,CircleUserRound,ClipboardList,Download,FileSpreadsheet,FileText,LayoutDashboard,LogIn,LogOut,Menu,Package,Plus,Search,Settings,ShoppingBag,Truck,Upload,UserPlus,X} from 'lucide-vue-next'
const authMode=ref('login'),currentUser=ref(null),businesses=ref([]),activeBusinessId=ref(null),activePage=ref('Dashboard'),mobileOpen=ref(false),showWorkspaceMenu=ref(false),showCreateBusiness=ref(false),notice=ref(''),search=ref(''),products=ref([]),movements=ref([]),suppliers=ref([]),importPreview=ref(null),showImporter=ref(false)
const demo={email:'jamie@stockpilot.demo',password:'demo1234',name:'Jamie Mejia'}
const configs={
'Retail Store':{item:'Products',focus:'Fast-moving retail stock',modules:['Dashboard','Products','Inventory','Stock Movements','Suppliers','Reports','Activity'],fields:['Barcode','Selling price','Category'],kpis:['Products','Units on hand','Inventory value','Low / out of stock'],quick:['Stock in','Stock out','Scan / add item'],hint:'Track shelf stock, barcodes and fast-moving items.'},
'Motorcycle Parts':{item:'Parts',focus:'Parts & compatibility',modules:['Dashboard','Parts','Inventory','Stock Movements','Suppliers','Compatibility','Reports','Activity'],fields:['Part number','Brand','Compatible model'],kpis:['Parts','Units on hand','Parts value','Reorder alerts'],quick:['Receive parts','Issue part','Add compatibility'],hint:'Organize parts by number, brand and vehicle compatibility.'},
'Food Business':{item:'Ingredients',focus:'Ingredients & expiry',modules:['Dashboard','Ingredients','Inventory','Recipes','Stock Movements','Suppliers','Expiry','Reports','Activity'],fields:['Unit','Batch','Expiry date'],kpis:['Ingredients','Stock units','Ingredient value','Expiring / low'],quick:['Receive ingredients','Use ingredients','Check expiry'],hint:'Watch ingredients, batches and expiry-sensitive stock.'},
'Online Seller':{item:'Items',focus:'Variants & reserved stock',modules:['Dashboard','Items','Inventory','Orders','Stock Movements','Suppliers','Reports','Activity'],fields:['Variant','Channel','Reserved stock'],kpis:['Items','Available units','Stock value','Low / reserved'],quick:['Add stock','Reserve stock','New order'],hint:'Manage SKUs, variants, orders and stock reserved for customers.'},
'Small Warehouse':{item:'Items',focus:'Locations & movement',modules:['Dashboard','Items','Inventory','Locations','Receiving','Dispatch','Transfers','Suppliers','Reports','Activity'],fields:['Rack','Bin','Location'],kpis:['SKUs','Units stored','Stock value','Reorder alerts'],quick:['Receive','Dispatch','Transfer'],hint:'Track where every item is stored and how it moves.'},
'Hardware Store':{item:'Materials',focus:'Bulk & unit inventory',modules:['Dashboard','Materials','Inventory','Stock Movements','Suppliers','Reports','Activity'],fields:['Unit','Brand','Selling price'],kpis:['Materials','Units on hand','Inventory value','Low stock'],quick:['Stock in','Stock out','Add material'],hint:'Handle pieces, boxes, meters and kilogram-based materials.'},
'Clothing Store':{item:'Styles',focus:'Size & color variants',modules:['Dashboard','Styles','Inventory','Variants','Stock Movements','Suppliers','Reports','Activity'],fields:['Size','Color','Collection'],kpis:['Styles','Variant units','Stock value','Low variants'],quick:['Receive variants','Sell / issue','Add variant'],hint:'Track each style across sizes, colors and collections.'},
'Electronics Store':{item:'Devices',focus:'Serials & warranty',modules:['Dashboard','Devices','Inventory','Serial Numbers','Stock Movements','Suppliers','Warranty','Reports','Activity'],fields:['Brand','Model','Serial number'],kpis:['Devices','Units on hand','Inventory value','Warranty / low'],quick:['Receive device','Issue device','Register serial'],hint:'Track models, individual serial numbers and warranties.'},
'Other':{item:'Products',focus:'Flexible inventory',modules:['Dashboard','Products','Inventory','Stock Movements','Suppliers','Reports','Activity'],fields:['SKU','Category','Notes'],kpis:['Products','Units on hand','Inventory value','Needs attention'],quick:['Stock in','Stock out','Add product'],hint:'A flexible inventory workspace you can configure later.'}}
const cfg=computed(()=>configs[activeBusiness.value?.type]||configs.Other)
const nav=computed(()=>cfg.value.modules.map(label=>[label,iconFor(label)]))
function iconFor(label){if(label==='Dashboard')return LayoutDashboard;if(['Products','Parts','Ingredients','Items','Materials','Styles','Devices'].includes(label))return Package;if(label==='Inventory')return ClipboardList;if(['Suppliers','Receiving','Dispatch','Transfers'].includes(label))return Truck;if(label==='Reports')return BarChart3;if(label==='Activity')return FileText;return Activity}
const activeBusiness=computed(()=>businesses.value.find(b=>b.id===activeBusinessId.value)||null),bp=computed(()=>products.value.filter(p=>p.business_id===activeBusinessId.value)),bm=computed(()=>movements.value.filter(m=>m.business_id===activeBusinessId.value)),bs=computed(()=>suppliers.value.filter(s=>s.business_id===activeBusinessId.value))
const status=p=>p.qty===0?'Out of stock':p.qty<=p.low?'Low stock':'Healthy',totalUnits=computed(()=>bp.value.reduce((a,p)=>a+(Number(p.qty)||0),0)),value=computed(()=>bp.value.reduce((a,p)=>a+(Number(p.qty)||0)*(Number(p.cost)||0),0)),attention=computed(()=>bp.value.filter(p=>status(p)!=='Healthy').length)
const money=v=>new Intl.NumberFormat('en-PH',{style:'currency',currency:activeBusiness.value?.currency||'PHP',maximumFractionDigits:0}).format(v),filtered=computed(()=>{const q=search.value.toLowerCase();return bp.value.filter(p=>!q||`${p.name} ${p.sku} ${p.category} ${p.extra||''}`.toLowerCase().includes(q))})
function flash(t){notice.value=t;setTimeout(()=>notice.value='',3000)}
function login(e){const f=new FormData(e.target);if(f.get('email')!==demo.email||f.get('password')!==demo.password)return flash('Use the preview credentials shown below.');currentUser.value={name:demo.name,email:demo.email};const b={id:1,name:'Mejia Moto Supply',type:'Motorcycle Parts',size:'Small (1–5 people)',currency:'PHP',trackSuppliers:true,lowStock:true,role:'OWNER'};businesses.value=[b];activeBusinessId.value=1;seedBusiness(b);flash('Welcome back, Jamie.')}
function register(e){const f=new FormData(e.target);currentUser.value={name:String(f.get('name')),email:String(f.get('email'))};businesses.value=[];activeBusinessId.value=null}
function seedBusiness(b){const sets={'Retail Store':[['Coca-Cola 1.5L','Beverages',35,12,55,'Barcode: 480198'],['Motorcycle Parts']],'Motorcycle Parts':[['Brake Pad Set','Brake System',18,10,280,'Honda/Yamaha · RCB'],['Engine Oil 1L','Lubricants',7,12,205,'10W-40 · Shell'],['Spark Plug CR8E','Ignition',42,15,95,'NGK · Multiple models']], 'Food Business':[['Rice 25kg','Ingredients',8,3,1250,'kg · Batch A12'],['Cooking Oil 5L','Ingredients',4,5,520,'5L · Exp 2027']], 'Online Seller':[['Classic T-Shirt','Apparel',24,8,180,'Black / M · Shopee'],['Canvas Tote','Accessories',6,8,120,'Natural · TikTok Shop']], 'Small Warehouse':[['Storage Box L','Storage',26,10,310,'Rack A · Bin 04'],['Packing Tape','Supplies',44,15,45,'Rack B · Bin 11']], 'Hardware Store':[['PVC Pipe 1/2','Plumbing',60,15,78,'piece · Atlanta'],['Portland Cement','Construction',24,10,265,'bag · Holcim']], 'Clothing Store':[['Classic Tee','Tops',32,8,190,'M / Black · Basics'],['Denim Jeans','Bottoms',14,5,480,'32 / Blue · Core']], 'Electronics Store':[['Wireless Router','Networking',12,4,1250,'TP-Link · Archer C6'],['SSD 1TB','Storage',9,5,2850,'Samsung · 870 EVO']], 'Other':[['Sample Product','General',20,5,100,'']]};const rows=sets[b.type]||sets.Other;rows.filter(Array.isArray).forEach((x,i)=>products.value.push({id:Date.now()+i,business_id:b.id,name:x[0],category:x[1],sku:`${b.id}-${String(i+1).padStart(3,'0')}`,qty:x[2],low:x[3],cost:x[4],extra:x[5]||''}));if(b.trackSuppliers)suppliers.value.push({id:Date.now(),business_id:b.id,name:b.type==='Motorcycle Parts'?'Davao Moto Supply':'Primary Supplier',contact:'supplier@example.com',items:2});if(rows[0])movements.value.push({id:Date.now(),business_id:b.id,type:'Stock In',item:rows[0][0],qty:'+12',user:currentUser.value.name,time:'Today'})}
function createBusiness(e){const f=new FormData(e.target),id=Date.now(),b={id,name:String(f.get('name')),type:String(f.get('type')),size:String(f.get('size')),currency:String(f.get('currency')),trackSuppliers:f.get('suppliers')==='yes',lowStock:f.get('alerts')==='yes',role:'OWNER',sales:String(f.get('sales'))};businesses.value.push(b);activeBusinessId.value=id;seedBusiness(b);showCreateBusiness.value=false;activePage.value='Dashboard';flash(`${b.name} was tailored for ${b.type}.`)}
function selectBusiness(id){activeBusinessId.value=id;showWorkspaceMenu.value=false;activePage.value='Dashboard'}function go(p){activePage.value=p;mobileOpen.value=false;search.value=''}function logout(){currentUser.value=null;businesses.value=[];activeBusinessId.value=null;products.value=[];movements.value=[];suppliers.value=[];activePage.value='Dashboard';authMode.value='login'}
function addProduct(){const n=prompt(`${cfg.value.item.slice(0,-1)||'Product'} name`);if(!n)return;products.value.push({id:Date.now(),business_id:activeBusinessId.value,name:n,category:'General',sku:`NEW-${bp.value.length+1}`,qty:0,low:5,cost:0,extra:''});flash(`${n} added.`)}function stock(p,d){p.qty=Math.max(0,(Number(p.qty)||0)+d);movements.value.unshift({id:Date.now(),business_id:activeBusinessId.value,type:d>0?'Stock In':'Stock Out',item:p.name,qty:(d>0?'+':'')+d,user:currentUser.value.name,time:'Just now'});flash(`${p.name} stock updated.`)}
const aliases={name:['name','product','product name','item','item name','description','part','part name','material','ingredient'],sku:['sku','item code','product code','code','part number','barcode'],category:['category','type','group','department'],qty:['qty','quantity','stock','stocks','on hand','current stock','stock on hand','inventory'],cost:['cost','cost price','buying price','purchase price','unit cost','price'],low:['low stock','reorder level','minimum stock','min stock','threshold','reorder point'],supplier:['supplier','vendor','supplier name']}
function norm(s){return String(s??'').trim().toLowerCase().replace(/[_-]+/g,' ').replace(/\s+/g,' ')}function findField(row,key){const keys=Object.keys(row);const wanted=aliases[key]||[];const k=keys.find(x=>wanted.includes(norm(x)));return k?row[k]:''}
async function importFile(e){const file=e.target.files?.[0];if(!file)return;try{const data=await file.arrayBuffer(),wb=XLSX.read(data),sheet=wb.Sheets[wb.SheetNames[0]],rows=XLSX.utils.sheet_to_json(sheet,{defval:''});if(!rows.length)return flash('No data rows found in that spreadsheet.');const mapped=rows.map((r,i)=>({row:i+2,name:String(findField(r,'name')).trim(),sku:String(findField(r,'sku')||`IMP-${Date.now()}-${i+1}`).trim(),category:String(findField(r,'category')||'Imported').trim(),qty:Number(findField(r,'qty'))||0,cost:Number(findField(r,'cost'))||0,low:Number(findField(r,'low'))||5,supplier:String(findField(r,'supplier')).trim(),raw:r}));const existing=new Set(bp.value.map(p=>norm(p.sku))),duplicates=mapped.filter(r=>existing.has(norm(r.sku))).length,needs=mapped.filter(r=>!r.name).length;importPreview.value={file:file.name,rows:mapped,duplicates,needs,ready:mapped.length-needs};showImporter.value=true}catch(err){flash('Could not read that file. Please use XLSX, XLS or CSV.')}e.target.value=''}
function confirmImport(){if(!importPreview.value)return;let added=0,skipped=0;const existing=new Set(bp.value.map(p=>norm(p.sku)));for(const r of importPreview.value.rows){if(!r.name||existing.has(norm(r.sku))){skipped++;continue}products.value.push({id:Date.now()+added,business_id:activeBusinessId.value,name:r.name,sku:r.sku,category:r.category,qty:r.qty,cost:r.cost,low:r.low,extra:r.supplier?`Supplier: ${r.supplier}`:''});existing.add(norm(r.sku));added++}movements.value.unshift({id:Date.now(),business_id:activeBusinessId.value,type:'Spreadsheet Import',item:`${added} records imported`,qty:`+${added}`,user:currentUser.value.name,time:'Just now'});showImporter.value=false;importPreview.value=null;flash(`${added} records imported; ${skipped} skipped for review/duplicates.`)}
function exportExcel(){const rows=bp.value.map(p=>({Name:p.name,SKU:p.sku,Category:p.category,Quantity:p.qty,'Reorder Level':p.low,'Cost Price':p.cost,Details:p.extra||'',Status:status(p)})),ws=XLSX.utils.json_to_sheet(rows),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Inventory');XLSX.writeFile(wb,`${activeBusiness.value.name.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}-inventory.xlsx`);flash('Excel export created.')}
</script>
<template><Transition name="page" mode="out-in">
<div v-if="!currentUser" class="auth-page" key="auth"><section class="auth-brand"><div class="auth-brand-copy"><div class="auth-logo"><Boxes :size="28"/></div><span class="eyebrow">Mejia Software</span><h1>StockPilot</h1><p>Inventory that adapts to the way your business actually works.</p><div class="visual-flow"><div class="flow-track"><span/></div><div class="flow-node node-user"><CircleUserRound :size="19"/><small>Account</small></div><div class="flow-node node-business"><Building2 :size="19"/><small>Business</small></div><div class="flow-node node-stock"><Package :size="19"/><small>Stock</small></div></div><div class="auth-feature"><Building2 :size="18"/><span><strong>Built around your business.</strong><small>Your modules, terminology and dashboard adapt to your industry.</small></span></div><div class="auth-feature"><FileSpreadsheet :size="18"/><span><strong>Bring your spreadsheet.</strong><small>Import existing Excel or CSV inventory instead of entering it one by one.</small></span></div></div></section><section class="auth-panel"><div class="auth-card"><div class="auth-tabs"><button :class="{active:authMode==='login'}" @click="authMode='login'">Log in</button><button :class="{active:authMode==='register'}" @click="authMode='register'">Register</button><span class="tab-slider" :class="{'tab-slider--register':authMode==='register'}"/></div><Transition name="auth-swap" mode="out-in"><div :key="authMode" class="auth-form-view"><template v-if="authMode==='login'"><span class="eyebrow">Welcome back</span><h2>Log in to StockPilot</h2><p>Open your business workspaces and continue where you left off.</p><form class="auth-form" @submit.prevent="login"><label>Email<input name="email" type="email" required/></label><label>Password<input name="password" type="password" required/></label><button class="primary-button auth-submit"><LogIn :size="17"/>Log in</button></form><div class="demo-credentials"><strong>Preview account</strong><span>jamie@stockpilot.demo</span><span>Password: demo1234</span></div></template><template v-else><span class="eyebrow">Start free</span><h2>Create your account</h2><p>Next, StockPilot asks about your business and builds the right inventory workspace.</p><form class="auth-form" @submit.prevent="register"><label>Full name<input name="name" required/></label><label>Email<input name="email" type="email" required/></label><label>Password<input name="password" type="password" minlength="8" required/></label><button class="primary-button auth-submit"><UserPlus :size="17"/>Continue to business setup</button></form></template></div></Transition></div></section></div>
<div v-else-if="!activeBusiness" class="onboarding-page" key="setup"><div class="onboarding-card onboarding-wide"><div class="modal-icon"><Building2 :size="24"/></div><span class="eyebrow">Adaptive workspace setup</span><h1>Tell us what you run</h1><p>These answers determine the modules, terminology, sample data and dashboard StockPilot creates for you.</p><form class="auth-form setup-grid" @submit.prevent="createBusiness"><label class="full">Business name<input name="name" required placeholder="e.g. Mejia Hardware"/></label><label>Business type<select name="type"><option>Retail Store</option><option>Motorcycle Parts</option><option>Food Business</option><option>Online Seller</option><option>Small Warehouse</option><option>Hardware Store</option><option>Clothing Store</option><option>Electronics Store</option><option>Other</option></select></label><label>Team size<select name="size"><option>Just me</option><option>Small (1–5 people)</option><option>Growing (6–20 people)</option><option>20+ people</option></select></label><label>Track suppliers?<select name="suppliers"><option value="yes">Yes</option><option value="no">Not right now</option></select></label><label>Low-stock alerts?<select name="alerts"><option value="yes">Yes</option><option value="no">No</option></select></label><label>Currency<select name="currency"><option value="PHP">PHP — Philippine Peso</option><option value="USD">USD — US Dollar</option></select></label><label>How do you operate?<select name="sales"><option>Physical store</option><option>Online</option><option>Both online and physical</option><option>Internal inventory only</option></select></label><button class="primary-button auth-submit full">Build my tailored workspace</button></form><button class="logout-link" @click="logout"><LogOut :size="15"/>Use another account</button></div></div>
<div v-else class="app-shell" key="app"><aside class="sidebar" :class="{'sidebar--open':mobileOpen}"><div class="brand-row"><div class="brand-mark"><Boxes :size="20"/></div><div><div class="brand-name">StockPilot</div><div class="brand-byline">by Mejia Software</div></div></div><div class="workspace-wrap"><button class="workspace-card" @click="showWorkspaceMenu=!showWorkspaceMenu"><div class="workspace-icon"><ShoppingBag :size="17"/></div><div class="workspace-copy"><strong>{{activeBusiness.name}}</strong><span>{{activeBusiness.type}}</span></div><ChevronDown :size="16"/></button><div v-if="showWorkspaceMenu" class="workspace-menu"><button v-for="b in businesses" :key="b.id" class="workspace-option" @click="selectBusiness(b.id)"><Building2 :size="16"/><span><strong>{{b.name}}</strong><small>{{b.type}}</small></span></button><button class="workspace-create" @click="showWorkspaceMenu=false;showCreateBusiness=true"><Plus :size="16"/>Create another business</button></div></div><nav class="nav-list"><button v-for="[label,Icon] in nav" :key="label" class="nav-item sidebar-link" :class="{'nav-item--active':activePage===label}" @click="go(label)"><component :is="Icon" :size="18"/>{{label}}</button></nav><div class="sidebar-bottom"><button class="nav-item sidebar-link" :class="{'nav-item--active':activePage==='Settings'}" @click="go('Settings')"><Settings :size="18"/>Settings</button><button class="nav-item logout-button" @click="logout"><LogOut :size="18"/>Log out</button></div></aside><main class="main-area"><header class="topbar"><button class="menu-button" @click="mobileOpen=true"><Menu/></button><div class="global-search"><Search :size="18"/><input v-model="search" :placeholder="`Search ${activePage.toLowerCase()}...`"/></div><div class="topbar-actions"><span class="tenant-pill"><Building2 :size="13"/>{{activeBusiness.name}}</span><button class="icon-button"><Bell :size="19"/></button></div></header><div class="content-wrap"><section class="hero-row"><div><span class="eyebrow">{{activeBusiness.type}} · {{cfg.focus}}</span><h1>{{activePage}}</h1><p>{{cfg.hint}}</p></div><div class="hero-actions"><label class="secondary-button file-button"><Upload :size="16"/>Import Excel<input type="file" accept=".xlsx,.xls,.csv" @change="importFile"/></label><button class="secondary-button" @click="exportExcel"><Download :size="16"/>Export</button><button v-if="['Dashboard',cfg.item,'Products','Parts','Ingredients','Items','Materials','Styles','Devices','Inventory'].includes(activePage)" class="primary-button" @click="addProduct"><Plus :size="17"/>Add {{cfg.item}}</button></div></section>
<template v-if="activePage==='Dashboard'"><div class="industry-banner"><div><strong>{{activeBusiness.type}} workspace</strong><span>{{cfg.hint}}</span></div><div class="industry-tags"><span v-for="f in cfg.fields" :key="f">{{f}}</span></div></div><section class="metric-grid"><article class="metric-card"><Package/><span class="metric-label">{{cfg.kpis[0]}}</span><strong>{{bp.length}}</strong></article><article class="metric-card"><Boxes/><span class="metric-label">{{cfg.kpis[1]}}</span><strong>{{totalUnits}}</strong></article><article class="metric-card"><BarChart3/><span class="metric-label">{{cfg.kpis[2]}}</span><strong>{{money(value)}}</strong></article><article class="metric-card"><AlertTriangle/><span class="metric-label">{{cfg.kpis[3]}}</span><strong>{{attention}}</strong></article></section><section class="quick-actions-section"><div class="section-heading"><span class="eyebrow">Designed for {{activeBusiness.type}}</span><h2>Common workflow</h2></div><div class="quick-action-grid"><button v-for="q in cfg.quick" :key="q" class="quick-action" @click="flash(`${q} workflow ready for ${activeBusiness.name}.`)"><span class="quick-icon"><Activity :size="19"/></span><span><strong>{{q}}</strong><small>{{activeBusiness.type}}</small></span></button></div></section><div class="dashboard-grid"><section class="panel"><div class="panel-header"><h2>{{cfg.item}} snapshot</h2><button class="text-button" @click="go(cfg.item)">View all</button></div><div class="table-wrap"><table><thead><tr><th>{{cfg.item}}</th><th>Category</th><th>Industry details</th><th>Stock</th><th>Status</th></tr></thead><tbody><tr v-for="p in bp.slice(0,5)" :key="p.id"><td><strong>{{p.name}}</strong><small class="cell-sub">{{p.sku}}</small></td><td>{{p.category}}</td><td>{{p.extra||'—'}}</td><td>{{p.qty}}</td><td><span class="status-badge">{{status(p)}}</span></td></tr></tbody></table></div></section><section class="panel"><div class="panel-header"><h2>Recent movements</h2></div><div class="movement-list"><div v-for="m in bm.slice(0,5)" :key="m.id" class="movement-row"><div class="movement-copy"><strong>{{m.item}}</strong><span>{{m.type}} · {{m.user}}</span></div><b>{{m.qty}}</b></div></div></section></div></template>
<template v-else-if="[cfg.item,'Products','Parts','Ingredients','Items','Materials','Styles','Devices'].includes(activePage)"><section class="panel"><div class="panel-header"><h2>{{cfg.item}} catalog</h2><span class="muted">{{filtered.length}} records</span></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>SKU / Code</th><th>Category</th><th>{{cfg.fields.join(' · ')}}</th><th>Cost</th><th>Stock</th></tr></thead><tbody><tr v-for="p in filtered" :key="p.id"><td><strong>{{p.name}}</strong></td><td>{{p.sku}}</td><td>{{p.category}}</td><td>{{p.extra||'—'}}</td><td>{{money(p.cost)}}</td><td>{{p.qty}}</td></tr></tbody></table></div></section></template>
<template v-else-if="activePage==='Inventory'"><section class="panel"><div class="panel-header"><h2>Live inventory</h2><span class="muted">Changes create movement records</span></div><div class="table-wrap"><table><thead><tr><th>Item</th><th>On hand</th><th>Reorder at</th><th>Status</th><th>Adjust</th></tr></thead><tbody><tr v-for="p in filtered" :key="p.id"><td><strong>{{p.name}}</strong></td><td>{{p.qty}}</td><td>{{p.low}}</td><td>{{status(p)}}</td><td><button class="mini-button" @click="stock(p,-1)">−</button><button class="mini-button" @click="stock(p,1)">+</button></td></tr></tbody></table></div></section></template>
<template v-else-if="activePage==='Stock Movements'"><section class="panel"><div class="movement-list"><div v-for="m in bm" :key="m.id" class="movement-row"><div><strong>{{m.item}}</strong><span>{{m.type}} · {{m.user}} · {{m.time}}</span></div><b>{{m.qty}}</b></div></div></section></template>
<template v-else-if="activePage==='Suppliers'"><section class="panel"><div v-if="!activeBusiness.trackSuppliers" class="empty-state"><Truck/><h2>Supplier tracking is off</h2><p>Enable it in Settings when this business starts purchasing from suppliers.</p></div><div v-else class="table-wrap"><table><thead><tr><th>Supplier</th><th>Contact</th><th>Items</th></tr></thead><tbody><tr v-for="s in bs" :key="s.id"><td><strong>{{s.name}}</strong></td><td>{{s.contact}}</td><td>{{s.items}}</td></tr></tbody></table></div></section></template>
<template v-else-if="activePage==='Reports'"><section class="metric-grid"><article class="metric-card"><strong>{{bp.length}}</strong><small>Total {{cfg.item.toLowerCase()}}</small></article><article class="metric-card"><strong>{{totalUnits}}</strong><small>Units on hand</small></article><article class="metric-card"><strong>{{money(value)}}</strong><small>Inventory value</small></article><article class="metric-card"><strong>{{attention}}</strong><small>Needs attention</small></article></section></template>
<template v-else-if="activePage==='Activity'"><section class="panel"><div class="movement-list"><div v-for="m in bm" :key="m.id" class="movement-row"><div><strong>{{m.user}} · {{m.type}}</strong><span>{{m.item}} · {{m.time}}</span></div><b>{{m.qty}}</b></div></div></section></template>
<template v-else-if="activePage==='Settings'"><section class="panel settings-grid"><div><span class="eyebrow">Business profile</span><h2>{{activeBusiness.name}}</h2><p>{{activeBusiness.type}} · {{activeBusiness.size}}</p></div><div><span class="eyebrow">Workspace engine</span><h2>{{cfg.focus}}</h2><p>Modules: {{cfg.modules.join(', ')}}</p></div></section></template>
<template v-else><section class="panel"><div class="empty-state"><Activity/><h2>{{activePage}}</h2><p>This {{activeBusiness.type}}-specific module is enabled because of the business profile. Its deeper workflow is the next implementation layer.</p></div></section></template>
</div></main>
<div v-if="showCreateBusiness" class="modal-backdrop"><div class="modal-card"><button class="modal-close" @click="showCreateBusiness=false"><X/></button><h2>Create another business</h2><form class="auth-form" @submit.prevent="createBusiness"><label>Name<input name="name" required/></label><label>Type<select name="type"><option v-for="(_,k) in configs" :key="k">{{k}}</option></select></label><input type="hidden" name="size" value="Just me"/><input type="hidden" name="currency" value="PHP"/><input type="hidden" name="suppliers" value="yes"/><input type="hidden" name="alerts" value="yes"/><input type="hidden" name="sales" value="Physical store"/><button class="primary-button">Create tailored workspace</button></form></div></div>
<div v-if="showImporter&&importPreview" class="modal-backdrop"><div class="modal-card import-card"><button class="modal-close" @click="showImporter=false"><X/></button><div class="modal-icon"><FileSpreadsheet/></div><span class="eyebrow">Smart spreadsheet import</span><h2>Review before importing</h2><p><strong>{{importPreview.file}}</strong> was analyzed and mapped to {{activeBusiness.type}} inventory fields.</p><div class="import-stats"><div><strong>{{importPreview.rows.length}}</strong><span>Rows detected</span></div><div><strong>{{importPreview.ready}}</strong><span>Ready</span></div><div><strong>{{importPreview.duplicates}}</strong><span>Duplicates</span></div><div><strong>{{importPreview.needs}}</strong><span>Need review</span></div></div><div class="mapping-note"><strong>Automatic column matching</strong><span>Recognizes common headings such as Product/Item Name, SKU/Code/Barcode, Qty/Stock/On Hand, Buying Price/Cost, Category, Supplier and Reorder Level. Duplicate SKUs and rows without names are skipped instead of silently overwriting data.</span></div><div class="import-preview-list"><div v-for="r in importPreview.rows.slice(0,5)" :key="r.row"><span>{{r.name||'⚠ Missing name'}}</span><small>{{r.sku}} · {{r.qty}} units · {{r.category}}</small></div></div><button class="primary-button modal-submit" @click="confirmImport"><Upload :size="16"/>Import {{importPreview.ready}} ready rows</button></div></div>
<transition name="toast"><div v-if="notice" class="toast">{{notice}}</div></transition></div></Transition></template>
